from __future__ import annotations

import re
import secrets
from urllib.parse import urlsplit

from linkvault.clock import format_ts

SLUG_RE = re.compile(r"^[A-Za-z0-9_-]{3,32}\Z")
ALPHABET = "abcdefghijklmnopqrstuvwxyz0123456789"
RESERVED = "healthz"
MAX_EXPIRES = 31536000


def valid_url(url):
    if not isinstance(url, str) or len(url) > 2048:
        return False
    if any(ord(c) < 0x21 or ord(c) == 0x7F for c in url):
        return False
    try:
        parts = urlsplit(url)
        return parts.scheme in ("http", "https") and bool(parts.hostname)
    except ValueError:
        return False


def validate_create(body):
    """Return (url, slug_or_None, expires_in_or_None) or raise ValueError(message)."""
    if not set(body) <= {"url", "slug", "expires_in"}:
        raise ValueError("unknown field")
    if not valid_url(body.get("url")):
        raise ValueError("url must be a valid http(s) URL up to 2048 characters")
    slug = body.get("slug")
    if "slug" in body and not (isinstance(slug, str) and SLUG_RE.match(slug)):
        raise ValueError("slug must match [A-Za-z0-9_-]{3,32}")
    exp = body.get("expires_in")
    if "expires_in" in body and not (
            isinstance(exp, int) and not isinstance(exp, bool) and 1 <= exp <= MAX_EXPIRES):
        raise ValueError("expires_in must be an integer from 1 to 31536000")
    return body["url"], slug, exp


def generate_slug():
    return "".join(secrets.choice(ALPHABET) for _ in range(7))


def link_object(row, port):
    ts = lambda v: None if v is None else format_ts(v)  # noqa: E731
    return {"slug": row["slug"], "url": row["url"],
            "short_url": "http://127.0.0.1:%d/%s" % (port, row["slug"]),
            "created_at": ts(row["created_at"]), "expires_at": ts(row["expires_at"]),
            "clicks": row["clicks"], "last_clicked_at": ts(row["last_clicked_at"])}
